import{_ as a,o as t,c as s,a2 as l}from"./chunks/framework.CDU0sSpB.js";const c=JSON.parse('{"title":"安全与隐私","description":"Hearth 的信任边界、威胁模型、Capability 模型、风险分级、凭据、Sandbox、提示词注入、隐私与事故响应。","frontmatter":{"title":"安全与隐私","description":"Hearth 的信任边界、威胁模型、Capability 模型、风险分级、凭据、Sandbox、提示词注入、隐私与事故响应。","outline":[2,3]},"headers":[],"relativePath":"architecture/security-privacy.md","filePath":"architecture/security-privacy.md","lastUpdated":1793706118000}'),n={name:"architecture/security-privacy.md"};function e(h,i,d,r,p,k){return t(),s("div",null,[...i[0]||(i[0]=[l(`<p class="eyebrow">SECURITY &amp; PRIVACY</p><h1 id="安全与隐私" tabindex="-1">安全与隐私 <a class="header-anchor" href="#安全与隐私" aria-label="Permalink to &quot;安全与隐私&quot;">​</a></h1><p class="lead">安全不是发布前检查，而是产品能力。信任边界、Capability、风险分级、凭据和事故响应都必须在架构中体现。</p><h2 id="安全是产品能力" tabindex="-1">安全是产品能力 <a class="header-anchor" href="#安全是产品能力" aria-label="Permalink to &quot;安全是产品能力&quot;">​</a></h2><p>Hearth 的安全不是“加一个审批弹窗”，而是贯穿来源、上下文、权限、执行、副作用和恢复的系统能力。模型不是可信执行环境，网页不是可信指令，文档不是可信代码，Connector 返回的数据也不是自动可信。</p><h3 id="信任边界" tabindex="-1">信任边界 <a class="header-anchor" href="#信任边界" aria-label="Permalink to &quot;信任边界&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不可信外部内容</span></span>
<span class="line"><span>  → Gateway 归一化</span></span>
<span class="line"><span>  → Policy / 数据标记</span></span>
<span class="line"><span>  → 最小上下文</span></span>
<span class="line"><span>  → Executor</span></span>
<span class="line"><span>  → Sandbox</span></span>
<span class="line"><span>  → Effect Dispatcher</span></span>
<span class="line"><span>  → 外部系统</span></span></code></pre></div><p>每一层都假设下一层可能被污染。外部内容可以影响任务内容，但不能扩大权限、修改 Policy 或直接触发高风险副作用。</p><h3 id="威胁模型" tabindex="-1">威胁模型 <a class="header-anchor" href="#威胁模型" aria-label="Permalink to &quot;威胁模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>威胁</th><th>场景</th><th>防线</th></tr></thead><tbody><tr><td>提示词注入</td><td>网页/邮件要求泄露文件或忽略规则</td><td>数据指令分离、工具白名单、不可信标记</td></tr><tr><td>凭据窃取</td><td>模型被诱导读取 token</td><td>Broker、最小注入、日志脱敏</td></tr><tr><td>数据外泄</td><td>恶意文档诱导上传</td><td>egress 白名单、DLP、只读挂载</td></tr><tr><td>重复副作用</td><td>超时后重试导致重复发信</td><td>幂等键、outbox、对账</td></tr><tr><td>恶意附件</td><td>宏、zip bomb、路径穿越</td><td>沙箱解析、宏禁用、资源限制</td></tr><tr><td>供应链</td><td>依赖/技能被篡改</td><td>锁版本、签名、SBOM、审阅</td></tr><tr><td>沙箱逃逸</td><td>恶意代码跳出容器</td><td>强隔离、非 root、无宿主 socket</td></tr><tr><td>记忆投毒</td><td>不可信来源写入长期偏好</td><td>quarantine、双来源、用户确认</td></tr><tr><td>设备丢失</td><td>手机或电脑被他人使用</td><td>撤销、过期、生物识别、加密</td></tr><tr><td>过度自动化</td><td>Agent 在无监督下扩大范围</td><td>Mandate、预算、kill switch</td></tr></tbody></table><h3 id="capability-模型" tabindex="-1">Capability 模型 <a class="header-anchor" href="#capability-模型" aria-label="Permalink to &quot;Capability 模型&quot;">​</a></h3><p>Capability 不是“某个 Agent 有某个工具”，而是对具体资源、动作、范围和期限的许可：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Capability</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  action</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  resource</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  scope</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  constraints</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  expiresAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  revokedAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  issuedBy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  mandateId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>原则：最小权限、短期有效、任务结束回收、按设备/账户/资源/动作限定、执行器不能自签或扩大、所有使用可审计、撤销立即生效。</p><h3 id="风险分级" tabindex="-1">风险分级 <a class="header-anchor" href="#风险分级" aria-label="Permalink to &quot;风险分级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>示例</th><th>默认处理</th></tr></thead><tbody><tr><td>R0 只读</td><td>查看文件、读邮件、搜索</td><td>可自动</td></tr><tr><td>R1 低风险写入</td><td>草稿、临时文件、工作区修改</td><td>在 Mandate 内自动</td></tr><tr><td>R2 外部可见</td><td>发送邮件、评论、分享</td><td>首次或每次审批</td></tr><tr><td>R3 不可逆</td><td>删除、付款、权限变更、公开发布</td><td>强审批 + 回执 + 补偿</td></tr><tr><td>R4 禁止</td><td>绕过安全控制、泄露秘密、未经授权转账</td><td>系统拒绝</td></tr></tbody></table><h3 id="凭据与秘密" tabindex="-1">凭据与秘密 <a class="header-anchor" href="#凭据与秘密" aria-label="Permalink to &quot;凭据与秘密&quot;">​</a></h3><ul><li>长期秘密只存在 Broker/密钥库；</li><li>模型上下文永远不包含 refresh token、私钥、cookie；</li><li>短期 token 只在调用外部 API 时注入；</li><li>日志、异常、截图和 Artifact 做敏感信息扫描；</li><li>开发、测试和生产使用不同凭据；</li><li>本地存储和备份加密；</li><li>支持按连接、设备和账户撤销；</li><li>用户可查看“谁在什么时候用了什么权限”。</li></ul><h3 id="sandbox、网络与提示词注入" tabindex="-1">Sandbox、网络与提示词注入 <a class="header-anchor" href="#sandbox、网络与提示词注入" aria-label="Permalink to &quot;Sandbox、网络与提示词注入&quot;">​</a></h3><ul><li>默认最小挂载和最短生命周期；</li><li>默认拒绝出站，按任务开白名单；</li><li>外部页面和文档标记为不可信；</li><li>不可信内容不能直接决定工具调用；</li><li>高风险动作必须经过 Effect Dispatcher 和审批；</li><li>下载物、宏和附件进入隔离区；</li><li>沙箱失败视为安全事件，不做“再试一次”掩盖。</li></ul><h3 id="隐私与本地优先" tabindex="-1">隐私与本地优先 <a class="header-anchor" href="#隐私与本地优先" aria-label="Permalink to &quot;隐私与本地优先&quot;">​</a></h3><ul><li>默认本地存储；</li><li>只上传任务需要的最小上下文；</li><li>敏感数据可指定本地模型或人工处理；</li><li>记忆、日志和 Artifact 有敏感级别；</li><li>删除和遗忘要传播；</li><li>备份加密；</li><li>数据导出和迁移可用；</li><li>不把用户数据用于未经同意的训练或共享。</li></ul><h3 id="供应链与扩展" tabindex="-1">供应链与扩展 <a class="header-anchor" href="#供应链与扩展" aria-label="Permalink to &quot;供应链与扩展&quot;">​</a></h3><ul><li>依赖锁版本、校验、SBOM；</li><li>技能/插件签名或来源验证；</li><li>第三方 Connector 最小权限；</li><li>插件不能绕过 Policy；</li><li>高风险扩展需人工审阅；</li><li>升级前跑安全与契约测试。</li></ul><h3 id="多设备安全" tabindex="-1">多设备安全 <a class="header-anchor" href="#多设备安全" aria-label="Permalink to &quot;多设备安全&quot;">​</a></h3><ul><li>设备配对使用短期码和公钥；</li><li>手机不持有长期主凭据；</li><li>审批绑定 nonce、参数和过期时间；</li><li>设备丢失可远程撤销；</li><li>离线缓存只读，不产生外部副作用；</li><li>跨设备只同步必要投影和产物引用；</li><li>记忆删除不能在另一设备复活。</li></ul><h3 id="事故响应与-kill-switch" tabindex="-1">事故响应与 kill switch <a class="header-anchor" href="#事故响应与-kill-switch" aria-label="Permalink to &quot;事故响应与 kill switch&quot;">​</a></h3><ul><li>全局停止开关；</li><li>按设备、连接器、技能、任务和账户的局部停止；</li><li>停止后保留审计和恢复入口；</li><li>密钥轮换；</li><li>事故后清理受影响凭据和缓存；</li><li>输出可读的事故报告；</li><li>不把“重启服务”当成事故处理。</li></ul><h3 id="备份、恢复与删除" tabindex="-1">备份、恢复与删除 <a class="header-anchor" href="#备份、恢复与删除" aria-label="Permalink to &quot;备份、恢复与删除&quot;">​</a></h3><ul><li>加密备份；</li><li>恢复后验证事件、产物、记忆和权限；</li><li>删除传播到投影、索引、缓存和设备；</li><li>保留最小审计所需信息，但不保留不应保留的敏感正文；</li><li>用户可导出自己的数据；</li><li>迁移后重新验证，不假设复制成功。</li></ul><h3 id="安全测试" tabindex="-1">安全测试 <a class="header-anchor" href="#安全测试" aria-label="Permalink to &quot;安全测试&quot;">​</a></h3><ul><li>提示词注入与工具越权；</li><li>秘密泄漏；</li><li>路径穿越、宏、zip bomb；</li><li>沙箱逃逸；</li><li>网络出口绕过；</li><li>审批重放；</li><li>设备撤销；</li><li>重复副作用；</li><li>供应链篡改；</li><li>记忆投毒；</li><li>数据和备份删除。</li></ul>`,32)])])}const y=a(n,[["render",e]]);export{c as __pageData,y as default};
